export type QualityLevel = 'low' | 'medium' | 'high' | 'ultra';

export interface QualityProfile {
  readonly level: QualityLevel;
  /** Upper bound for the renderer pixel ratio. */
  readonly maxPixelRatio: number;
  readonly shadows: boolean;
  /** Multiplier applied to every particle burst. */
  readonly particleScale: number;
  /** Hard cap on simultaneously live particles. */
  readonly particleBudget: number;
}

export const QUALITY_PROFILES: Record<QualityLevel, QualityProfile> = {
  low: { level: 'low', maxPixelRatio: 1, shadows: false, particleScale: 0.35, particleBudget: 96 },
  medium: { level: 'medium', maxPixelRatio: 1.5, shadows: true, particleScale: 0.7, particleBudget: 256 },
  high: { level: 'high', maxPixelRatio: 2, shadows: true, particleScale: 1, particleBudget: 512 },
  ultra: { level: 'ultra', maxPixelRatio: 2.5, shadows: true, particleScale: 1.5, particleBudget: 768 },
};

/** The particle pool is allocated once, so it is sized for the richest preset. */
export const PARTICLE_POOL_CAPACITY = QUALITY_PROFILES.ultra.particleBudget;

/** Unknown or missing presets fall back to the shipped default. */
export function qualityProfile(level: QualityLevel | string | undefined): QualityProfile {
  return level === 'low' || level === 'medium' || level === 'ultra' ? QUALITY_PROFILES[level] : QUALITY_PROFILES.high;
}

/** Structural view of core/Renderer; keeps the settings plumbing testable without WebGL. */
export interface QualityTarget {
  setMaxPixelRatio(ratio: number): number;
  setShadowsEnabled(enabled: boolean): void;
}

/** Pushes a menu preset into the renderer and reports what was applied. */
export function applyQuality(target: QualityTarget, level: QualityLevel | string | undefined): QualityProfile {
  const profile = qualityProfile(level);
  target.setMaxPixelRatio(profile.maxPixelRatio);
  target.setShadowsEnabled(profile.shadows);
  return profile;
}

/** Menu slider (0..100) to a linear mixer gain. */
export function volumeToGain(volume: number | undefined): number {
  if (typeof volume !== 'number' || !Number.isFinite(volume)) return 1;
  return Math.min(1, Math.max(0, volume / 100));
}
