import type { AudioCategory, AudioEventDefinition } from './AudioManager';

const CATEGORIES: readonly AudioCategory[] = ['music', 'sfx', 'ui', 'ambient'];

export interface ManifestResponse {
  ok: boolean;
  status: number;
  json(): Promise<unknown>;
}

export type ManifestFetch = (url: string) => Promise<ManifestResponse>;

export interface ManifestSink {
  registerMany(definitions: readonly AudioEventDefinition[]): void;
}

export const AUDIO_MANIFEST_URL = '/audio/manifest.json';

/** Reads `public/audio/manifest.json`; malformed entries are skipped, not fatal. */
export function parseAudioManifest(value: unknown): AudioEventDefinition[] {
  const events = (value as { events?: unknown } | null)?.events;
  if (!Array.isArray(events)) return [];
  const parsed: AudioEventDefinition[] = [];
  for (const entry of events) {
    const item = entry as Partial<AudioEventDefinition> | null;
    if (!item || typeof item.id !== 'string' || typeof item.url !== 'string') continue;
    const category = CATEGORIES.find((known) => known === item.category);
    if (!category) continue;
    const definition: AudioEventDefinition = {
      id: item.id,
      url: item.url,
      category,
      loop: item.loop === true,
      // Placeholder audio may be missing from the checkout, so events stay optional by default.
      optional: item.optional !== false,
    };
    if (typeof item.volume === 'number' && Number.isFinite(item.volume)) definition.volume = item.volume;
    parsed.push(definition);
  }
  return parsed;
}

/** Registers every manifest event on the mixer; a missing manifest is not an error. */
export async function registerAudioManifest(
  sink: ManifestSink,
  url: string = AUDIO_MANIFEST_URL,
  fetchImpl?: ManifestFetch,
): Promise<readonly AudioEventDefinition[]> {
  const request = fetchImpl ?? (globalThis.fetch as unknown as ManifestFetch | undefined);
  if (!request) return [];
  try {
    const response = await request(url);
    if (!response.ok) return [];
    const events = parseAudioManifest(await response.json());
    if (events.length > 0) sink.registerMany(events);
    return events;
  } catch {
    return [];
  }
}
